using Alterverse.Characters;using Alterverse.Match;using Alterverse.Visuals;using UnityEngine;
namespace Alterverse.Combat
{
[RequireComponent(typeof(DimensionPlanet),typeof(Health))]public sealed class PlanetMeteorShower:MonoBehaviour
{
[SerializeField]private float radius=11f,cooldown=8.5f,telegraph=1.55f,damage=14f;[SerializeField]private int meteors=7;private const int HeroScanBufferSize=32;private readonly Collider[] heroScanBuffer=new Collider[HeroScanBufferSize];private Health self;private DimensionPlanet planet;private float next,nextHeroScan;private bool heroNearby;
private void Awake(){self=GetComponent<Health>();planet=GetComponent<DimensionPlanet>();next=Time.time+3f;}
private void Update(){if(Time.timeScale<=0||self==null||self.IsDead||planet==null||!planet.Available||Time.time<next)return;if(Time.time>=nextHeroScan){nextHeroScan=Time.time+.25f;heroNearby=HasHero();}if(!heroNearby)return;next=Time.time+cooldown;for(int i=0;i<meteors;i++){Vector2 r=Random.insideUnitCircle*radius;Vector3 p=transform.position+new Vector3(r.x,0,r.y);MeteorStrike.Create(p,telegraph,damage,i*.16f,planet);}}
private bool HasHero(){int hits=Physics.OverlapSphereNonAlloc(transform.position,radius,heroScanBuffer);for(int i=0;i<hits;i++){Collider c=heroScanBuffer[i];if(c==null)continue;TeamMember m=c.GetComponentInParent<TeamMember>();if(m==null)continue;Health h=m.GetComponent<Health>();if(h!=null&&!h.IsDead)return true;}return false;}
}
public sealed class MeteorStrike:MonoBehaviour
{
private const int HitBufferSize=32;private readonly Collider[] hitBuffer=new Collider[HitBufferSize];private float hitAt,damage;private GameObject warning,meteor;private Vector3 startPosition;private DimensionPlanet owner;private DimensionsFront front;public static void Create(Vector3 p,float delay,float dmg,float stagger,DimensionPlanet sourcePlanet){GameObject g=new GameObject("DF_MeteorStrike");g.transform.position=p;MeteorStrike s=g.AddComponent<MeteorStrike>();s.damage=dmg;s.hitAt=Time.time+delay+stagger;s.startPosition=p;s.owner=sourcePlanet;s.front=sourcePlanet!=null?sourcePlanet.GetComponentInParent<DimensionsFront>():null;if(s.front==null)s.front=FindAnyObjectByType<DimensionsFront>();Transform world=GameObject.Find("DF_MatchWorld")?.transform;if(world!=null)g.transform.SetParent(world,true);s.warning=GameObject.CreatePrimitive(PrimitiveType.Cylinder);s.warning.name="DF_MeteorWarning";if(world!=null)s.warning.transform.SetParent(world,true);s.warning.transform.position=p+Vector3.up*.03f;s.warning.transform.localScale=new Vector3(2.1f,.02f,2.1f);Collider c=s.warning.GetComponent<Collider>();if(c!=null)c.enabled=false;Renderer r=s.warning.GetComponent<Renderer>();if(r!=null)r.material.color=new Color(1f,.2f,.05f,.38f);s.meteor=GameObject.CreatePrimitive(PrimitiveType.Sphere);if(world!=null)s.meteor.transform.SetParent(world,true);s.meteor.transform.position=p+Vector3.up*9f;s.meteor.name="DF_FallingMeteor";s.meteor.transform.localScale=Vector3.one*.7f;Collider mc=s.meteor.GetComponent<Collider>();if(mc!=null)mc.enabled=false;Renderer mr=s.meteor.GetComponent<Renderer>();if(mr!=null)mr.material.color=new Color(1f,.32f,.08f);}
private void Update(){if(owner==null||!owner.Available){Destroy(gameObject);return;}if(front!=null&&front.HasEnded){Destroy(gameObject);return;}if(Time.time<hitAt){if(meteor!=null){float remain=Mathf.Max(0,hitAt-Time.time);float height=Mathf.Lerp(.35f,9f,Mathf.Clamp01(remain/1.7f));meteor.transform.position=startPosition+Vector3.up*height;}return;}PrototypeVfx.RadialBurst(transform.position+Vector3.up*.1f,new Color(1f,.28f,.06f),2.1f);int hits=Physics.OverlapSphereNonAlloc(transform.position,2.1f,hitBuffer);for(int i=0;i<hits;i++){Collider c=hitBuffer[i];if(c==null)continue;Health h=c.GetComponentInParent<Health>();if(h==null||h.IsDead)continue;bool alreadyHit=false;for(int j=0;j<i;j++){Collider prior=hitBuffer[j];if(prior!=null&&prior.GetComponentInParent<Health>()==h){alreadyHit=true;break;}}if(alreadyHit)continue;if(h.GetComponent<RealityCore>()!=null||h.GetComponent<LaneTower>()!=null||h.GetComponent<DimensionPlanet>()!=null)continue;if(h.GetComponent<TeamMember>()==null&&h.GetComponent<LaneMinion>()==null)continue;h.TakeDamage(damage,gameObject);}if(warning!=null)Destroy(warning);if(meteor!=null)Destroy(meteor);Destroy(gameObject);}
private void OnDestroy(){if(warning!=null)Destroy(warning);if(meteor!=null)Destroy(meteor);}
}
}
